import React from 'react';
import styled from 'styled-components';

const Services = () => {
    return (
        <div>
            <Title>
                Nasza oferta
            </Title>
            <MainBox>
                <BoxesRow>
                    <Subtitle>Ryczałt od przychodów ewidencjonowanych</Subtitle>
                    <ServiceList>
                        <ListItem>Kontrola dokumentów pod względem formalno-rachunkowym</ListItem>
                        <ListItem>Prowadzenie ewidencji przychodów</ListItem>
                        <ListItem></ListItem>
                        <ListItem></ListItem>
                    </ServiceList>
                </BoxesRow>
            </MainBox>
        </div>

    );
}

export default Services

const MainBox = styled.div`
    height: 800px;
    margin: 48px;
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    justify-content: flex-start;
`;

const Title = styled.h1`
    padding-top: 48px;
    padding-bottom: 48px; 
    text-align: center;
`;

const BoxesRow = styled.div`
    display: flex;
    flex-direction: row;
    height: auto;
    width: 100%;
    align-items: sTableRowetch;
    justify-content: center;
    background-color: #E5A424;
    border-radius: 25px;
`;

const Spacer = styled.div`
    flex: 10%;
`;

const Subtitle = styled.h2`
    text-align: center;
    padding: 20px;
    color: #fff;
`;

const ServiceList = styled.ul`
    list-style-type: none;
    align-content: center;
`;

const ListItem = styled.li`
    text-align: left;
    font-family: 'Source Sans Pro', sans-serif;
    padding: 10px;
    padding-left: 35px;
`;
